<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { consultarLibroMayor, obtenerOpcionesLibroMayor } from '../services/libroMayor'
import type { FiltrosLibroMayor, LibroMayorData, PeriodoLibroMayor } from '../interfaces/libroMayor.interface'
const filtros=reactive<FiltrosLibroMayor>({detalle_periodo_id:null,vista:'analitica'}),periodos=ref<PeriodoLibroMayor[]>([]),data=ref<LibroMayorData|null>(null),loading=ref(false),consultado=ref(false),error=ref('')
const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la consulta.'
const money=(v:number|null|undefined)=>`S/ ${new Intl.NumberFormat('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v||0))}`
async function load(){loading.value=true;try{const r=await obtenerOpcionesLibroMayor();periodos.value=r.periodos;data.value=r.data;const vigente=r.periodos.find(p=>p.vigente);if(vigente)filtros.detalle_periodo_id=vigente.id}catch(v){error.value=message(v)}finally{loading.value=false}}
async function search(){error.value='';if(!filtros.detalle_periodo_id)return void(error.value='Seleccione un periodo contable.');loading.value=true;consultado.value=true;try{data.value=(await consultarLibroMayor(filtros)).data}catch(v){error.value=message(v);data.value=null}finally{loading.value=false}}
function clear(){filtros.detalle_periodo_id=null;filtros.vista='analitica';data.value=null;consultado.value=false;error.value=''}
onMounted(load)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/administracion/contabilidad/proceso-contable">Proceso contable</RouterLink> / Libro mayor general</nav><header class="hero"><div class="mark">LM</div><div><small>MIA · CONTABILIDAD · PROCESO</small><h1>Libro mayor general</h1><p>Movimientos agrupados por cuenta contable con saldos acumulados.</p></div></header><p v-if="error" class="flash">{{error}}</p><form class="filters" @submit.prevent="search"><label>Periodo contable *<select v-model="filtros.detalle_periodo_id"><option :value="null">Seleccione</option><option v-for="p in periodos" :key="p.id" :value="p.id">{{p.codigo}} - {{p.mes_label}} {{p.anio}}</option></select></label><label>Vista<select v-model="filtros.vista"><option value="analitica">Analítica (por cuenta)</option><option value="resumida">Resumida (totales)</option></select></label><footer><button type="button" class="soft" @click="clear">Limpiar</button><button :disabled="loading">{{loading?'Consultando…':'Consultar'}}</button></footer></form><div v-if="loading" class="empty">Preparando el libro mayor…</div><div v-else-if="consultado&&!data?.cuentas.length" class="empty">No se encontraron movimientos para el periodo seleccionado.</div><div v-else-if="!data" class="empty">Seleccione un periodo contable para visualizar el libro mayor general.</div><main v-else><header class="summary"><div><b>Periodo</b><span>{{data.periodo.codigo}} · {{data.periodo.mes_label}} {{data.periodo.anio}}</span></div><div><b>Cuentas con movimiento</b><span>{{data.cuentas.length}}</span></div><div><b>Total debe acumulado</b><span>{{money(data.totalGeneralDebe)}}</span></div><div><b>Total haber acumulado</b><span>{{money(data.totalGeneralHaber)}}</span></div></header><section v-for="cuenta in data.cuentas" :key="cuenta.cta_contable" class="account"><header><b>{{cuenta.cta_contable}} - {{cuenta.descripcion}}</b><span>Naturaleza: {{cuenta.naturaleza}}</span></header><div class="scroll"><table v-if="filtros.vista==='analitica'"><thead><tr><th>Fecha</th><th>Tipo comprobante</th><th>N.° comprobante</th><th class="num">Debe S/</th><th class="num">Haber S/</th></tr></thead><tbody><tr class="initial"><td colspan="3"><b>SALDO INICIAL</b><small v-if="!cuenta.saldo_inicial_debe&&!cuenta.saldo_inicial_haber"> Sin saldo inicial registrado</small></td><td class="num">{{money(cuenta.saldo_inicial_debe)}}</td><td class="num">{{money(cuenta.saldo_inicial_haber)}}</td></tr><tr v-for="(mov,i) in cuenta.movimientos??[]" :key="`${mov.numero_comprobante}-${i}`"><td>{{mov.fecha}}</td><td>{{mov.tipo_codigo}} - {{mov.tipo_nombre}}</td><td>{{mov.numero_comprobante}}</td><td class="num">{{money(mov.debe)}}</td><td class="num">{{money(mov.haber)}}</td></tr><tr v-if="!cuenta.movimientos?.length"><td colspan="5" class="center">Sin movimientos en esta cuenta.</td></tr><tr class="month"><td colspan="3"><b>TOTAL DEL MES</b></td><td class="num">{{money(cuenta.total_debe_mov)}}</td><td class="num">{{money(cuenta.total_haber_mov)}}</td></tr><tr class="balance"><td colspan="3"><b>SALDO FINAL</b></td><td colspan="2" class="center"><b>{{cuenta.saldo_final_tipo}} {{money(cuenta.saldo_final)}}</b></td></tr></tbody></table><table v-else><thead><tr><th>Concepto</th><th class="num">Debe S/</th><th class="num">Haber S/</th></tr></thead><tbody><tr class="initial"><td><b>SALDO INICIAL</b></td><td class="num">{{money(cuenta.saldo_inicial_debe)}}</td><td class="num">{{money(cuenta.saldo_inicial_haber)}}</td></tr><tr class="month"><td><b>TOTAL DEL MES</b></td><td class="num">{{money(cuenta.total_debe_mov)}}</td><td class="num">{{money(cuenta.total_haber_mov)}}</td></tr><tr class="balance"><td><b>SALDO FINAL</b></td><td colspan="2" class="center"><b>{{cuenta.saldo_final_tipo}} {{money(cuenta.saldo_final)}}</b></td></tr></tbody></table></div></section></main></div></template>
<style scoped>
.page{--a:#655b9c;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--a);text-decoration:none}.hero{padding:20px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero small{color:var(--a);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.flash{padding:9px;color:#a64046;background:#fff0f0}.filters{margin-top:12px;padding:15px;display:grid;grid-template-columns:2fr 1.5fr 1fr;gap:8px;background:#fff}.filters label{display:grid;gap:5px;font-size:.49rem}.filters select{min-width:0;padding:9px;border:1px solid #d7dfe2;border-radius:6px;background:#fff;font:inherit;font-size:.52rem}.filters footer{display:flex;align-items:end;justify-content:flex-end;gap:6px}.filters button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.52rem}.soft{color:#64727a!important;background:#edf1f3!important}.empty{margin-top:12px;padding:45px;text-align:center;background:#fff}.summary{margin-top:14px;padding:12px;display:grid;grid-template-columns:repeat(4,1fr);gap:8px;background:#fff}.summary div{display:grid;gap:3px;font-size:.52rem}.summary b{color:#728087}.account{margin-top:14px;background:#fff}.account>header{padding:10px 14px;display:flex;justify-content:space-between;color:#fff;background:#2c3e50;font-size:.58rem}.account>header span{padding:3px 7px;border-radius:10px;color:#35464e;background:#fff;font-size:.46rem}.scroll{overflow:auto}table{width:100%;min-width:700px;border-collapse:collapse;font-size:.5rem}th,td{padding:8px;border:1px solid #e1e7ea;text-align:left}thead{color:#fff;background:#465966}.num{text-align:right;font-family:monospace}.center{text-align:center}.initial{background:#fff9e4}.initial small{color:#7b858a}.month{background:#dce2e4}.month td:first-child{text-align:right}.balance{background:#e2f4ec;border-left:4px solid #2aa675}.balance td:first-child{text-align:right}@media(max-width:800px){.summary{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.filters,.summary{grid-template-columns:1fr}.filters footer{justify-content:flex-start}}
</style>
